SELECT u.USERID, u.USERNAME, a.MARKET
FROM HDOC_USER_INFOR u
INNER JOIN HDOC_MARKET_AUTH a ON u.USERID = a.USERID
WHERE u.USERID = #{userid}
AND a.MARKET = #{market}

SELECT u.USERID, u.USERNAME, a.MARKET FROM HDOC_USER_INFOR u INNER JOIN HDOC_MARKET_AUTH a ON u.USERID = a.USERID
a.MARKET = #{market}
ORDER BY u.USERID
